/**
 * Static mock product data for the landing page mini-studio.
 * Data extracted directly from the product CSV with actual placement coordinates.
 * Uses StudioRenderedItem structure compatible with OutfitInspirationTile.
 */

import type {
  MannequinSegmentName,
  MannequinConfig,
  StudioPlacementByMannequin,
  StudioRenderedItem,
  StudioRenderedZone,
} from "@/features/studio/types"

export type LandingMockProduct = {
  id: string
  type: "top" | "bottom" | "shoes"
  brand: string
  price: number
  currency: string
  imageUrl: string
  /**
   * Small WebP for grid tiles. NEVER for the mannequin — the placement transform is measured
   * against the full image (see renderedItemMapper), so wearing a 400px thumbnail would shift the
   * garment and misapply the warp lattice, whose offsets are in source-texture pixels.
   */
  thumbnailUrl?: string | null
  productName: string
  // Placement data for mannequin rendering (from CSV)
  placementX: number
  placementY: number
  imageLengthCm: number
  gender?: "male" | "female" | "unisex"
  // Body parts visible - controls which mannequin segments are shown
  bodyPartsVisible?: MannequinSegmentName[] | null
  // Marks one-piece items (dresses/jumpsuits) that should hide bottoms in mini studio
  isDress?: boolean
  /**
   * Canvas transform for the photoreal mannequin, when this product has been placed.
   *
   * Only the default outfits carry one — populated from the catalog by
   * scripts/list-placed-outfit-candidates.ts. The alternates have none, which is deliberate: the
   * mini studio renders the photoreal figure only while every garment on the body is placed, and
   * falls back to the legacy SVG avatar otherwise. The 2D fields above stay populated on every
   * product precisely so that fallback still works.
   */
  placement?: StudioPlacementByMannequin | null
}

// Alternative products for the grid - extracted from CSV with real placement data
/**
 * Grid alternatives: every one is 3D-placed, same as the default outfits.
 *
 * That is a hard requirement, not a nicety. The mini studio renders the photoreal mannequin only
 * while EVERY garment on the body is placed, so a single unplaced alternate drops the whole
 * outfit to the legacy SVG renderer -- which positions garments from placement_x/placement_y/
 * image_length, and this catalog has none of those. The result would be the remaining garment
 * drawn at the origin with zero length. Keep this list all-placed.
 *
 * Emitted by scripts/list-placed-outfit-candidates.ts --emit-alternates.
 */
